      security1: { sie: 'Les données utilisateur ne quittent jamais votre appareil. Toutes les connexions au site sont chiffrées en HTTPS. Le code source est accessible publiquement.', du: 'Les données utilisateur ne quittent jamais ton appareil. Toutes les connexions au site sont chiffrées en HTTPS. Le code source est accessible publiquement.' },
      security2: { sie: 'Les données étant stockées localement, la sécurité relève de votre responsabilité : protégez votre appareil par un mot de passe et effectuez des sauvegardes régulières.', du: 'Les données étant stockées localement, la sécurité relève de ta responsabilité : protège ton appareil par un mot de passe et effectue des sauvegardes régulières.' },
